# ── Import logic ─────────────────────────────────────────────────────────────
from exams.models import Copy
from grading.models import Score, GradingEvent
from django.contrib.auth import get_user_model
from django.utils import timezone

User = get_user_model()
laroussi = User.objects.get(username="laroussi.laroussi@ert.tn")

created = 0
updated = 0
skipped = 0
errors = []

print("=" * 70)
print("IMPORT SCORES LAROUSSI — localStorage Recovery")
print(f"Date: {datetime.now().isoformat()}")
print(f"Source: korrigo_recovery_V3_2026-03-02T10-58-49.json")
print(f"Corrector: {laroussi.username} (id={laroussi.id})")
print(f"Scores to import: {len(SCORES_DATA)}")
print("=" * 70)

for anon_id, entry in sorted(SCORES_DATA.items()):
    scores_data = entry["scores_data"]
    nq = entry["nq"]
    total = entry["total"]

    try:
        copy = Copy.objects.get(anonymous_id=anon_id)
    except Copy.DoesNotExist:
        errors.append(f"{anon_id}: Copy NOT FOUND")
        print(f"  ERROR {anon_id}: Copy not found in DB")
        continue

    # Check existing score
    existing = Score.objects.filter(copy=copy).first()
    if existing and existing.scores_data:
        old_nq = len(existing.scores_data)
        if old_nq >= nq:
            skipped += 1
            print(f"  SKIP  {anon_id}: existing score has {old_nq}q >= recovery {nq}q")
            continue
        else:
            # Recovery has MORE questions — update
            existing.scores_data = scores_data
            existing.save()
            updated += 1
            print(f"  UPDATE {anon_id}: {old_nq}q -> {nq}q, total={total:.2f}")
    else:
        # Create new score
        Score.objects.create(
            copy=copy,
            scores_data=scores_data,
        )
        created += 1
        print(f"  CREATE {anon_id}: {nq}q, total={total:.2f}")

    # Log grading event
    GradingEvent.objects.create(
        copy=copy,
        actor=laroussi,
        action="ls_recovery",
        metadata={
            "source": "korrigo_recovery_V3_2026-03-02T10-58-49.json",
            "old_uuid": entry["old_uuid"],
            "nq": nq,
            "total": total,
            "imported_at": datetime.now().isoformat(),
        }
    )

print()
print("=" * 70)
print(f"RESULTS: created={created}, updated={updated}, skipped={skipped}, errors={len(errors)}")
if errors:
    print(f"Errors: {errors}")
print("=" * 70)
